import secrets, string, sys

def gen(length=20, require_symbol=True):
    upper, lower, digits = string.ascii_uppercase, string.ascii_lowercase, string.digits
    symbols = "!@#$%^&*-_=+?"
    pools = [upper, lower, digits] + ([symbols] if require_symbol else [])
    while True:
        pw = ''.join(secrets.choice(''.join(pools)) for _ in range(length))
        if all(any(c in p for c in pw) for p in pools):
            return pw

if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else {{length}}
    print(gen(n, require_symbol={{require_symbol}}))
